    </linearGradient>
    ${hairColorLayers(uid + '-hair', hair)}
    <linearGradient id="${uid}-gold" x1="0" y1="0" x2="0.6" y2="1">
      <stop offset="0" stop-color="#fff1c8"/><stop offset=".5" stop-color="#e2bf7f"/><stop offset="1" stop-color="#a9803f"/>
    </linearGradient>
    <radialGradient id="${uid}-vig" cx="50%" cy="44%" r="68%">
      <stop offset=".55" stop-color="#07060d" stop-opacity="0"/>
      <stop offset="1" stop-color="#07060d" stop-opacity=".6"/>
    </radialGradient>
    <filter id="${uid}-blur" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="7"/></filter>
    <filter id="${uid}-eye-174-blur" x="-80%" y="-80%" width="260%" height="260%"><feGaussianBlur stdDeviation="3.2"/></filter>
    <filter id="${uid}-eye-226-blur" x="-80%" y="-80%" width="260%" height="260%"><feGaussianBlur stdDeviation="3.2"/></filter>
  </defs>
  <g>
    <circle cx="200" cy="190" r="198" fill="url(#${uid}-aura)"/>
    <g class="portrait-orbit" style="transform-origin:200px 190px">
      <circle cx="200" cy="190" r="168" fill="none" stroke="${accent}" stroke-opacity=".22" stroke-width="1" stroke-dasharray="2 9"/>
      <circle cx="200" cy="190" r="154" fill="none" stroke="${accent}" stroke-opacity=".1" stroke-width="1"/>
    </g>
    ${rays}
    ${motes}

    <!-- shoulders -->
    <path d="M200 320 C${200 - sw * .55} 320 ${200 - sw * .85} 336 ${200 - sw} 356 C${200 - sw * 1.18} 388 ${200 - sw * 1.33} 450 ${200 - sw * 1.42} 520 L${200 + sw * 1.42} 520 C${200 + sw * 1.33} 450 ${200 + sw * 1.18} 388 ${200 + sw} 356 C${200 + sw * .85} 336 ${200 + sw * .55} 320 200 320 Z" fill="url(#${uid}-robe)" stroke="${accent}" stroke-opacity=".28" stroke-width="1.2"/>
    <path d="M200 322 L168 332 C176 364 188 388 200 400 C212 388 224 364 232 332 Z" fill="${skinDark}"/>
    <path d="M168 330 C178 364 190 388 200 400 C210 388 222 364 232 330" fill="none" stroke="#e5c485" stroke-opacity=".55" stroke-width="2"/>
    <path d="M118 374 C146 358 172 352 200 352 C228 352 254 358 282 374" fill="none" stroke="${accent}" stroke-opacity=".18" stroke-width="8"/>
    <circle cx="200" cy="326" r="4" fill="url(#${uid}-gold)"/>
    <path d="M100 448 C130 480 160 500 200 500 C240 500 270 480 300 448" fill="none" stroke="${accent}" stroke-opacity=".16" stroke-width="10"/>

    <!-- neck -->
    <path d="M174 238 L226 238 L234 306 C234 318 244 326 254 330 L146 330 C156 326 166 318 166 306 Z" fill="${skinDark}"/>

    ${backHair}
    ${ears}
    <path d="${head}" fill="url(#${uid}-skin)" stroke="${skinDark}" stroke-opacity=".28" stroke-width="1"/>
    <path d="M200 84 C246 84 270 120 270 166 C270 214 242 254 200 266 C158 254 130 214 130 166 C130 120 154 84 200 84 Z" fill="none" stroke="${skinDark}" stroke-opacity=".12"/>
    <ellipse cx="200" cy="222" rx="42" ry="24" fill="${skinDark}" opacity=".1"/>
    <ellipse cx="166" cy="202" rx="20" ry="13" fill="#ffffff" opacity=".08"/>
    <ellipse cx="234" cy="202" rx="20" ry="13" fill="#ffffff" opacity=".06"/>
    <ellipse cx="186" cy="118" rx="26" ry="12" fill="#ffffff" opacity=".07"/>
    ${complexionFx}

    ${eyes}

    <path d="M199 174 C196 190 193 197 189 204 C194 208 202 208 207 205" fill="none" stroke="${skinDark}" stroke-opacity=".55" stroke-width="2.2" stroke-linecap="round"/>
    <path d="M187 227 Q194 221 200 226 Q206 221 213 227 Q206 237 200 237 Q194 237 187 227 Z" fill="${mix(skin, '#a8505c', .55)}"/>
    <path d="M187 227 Q194 222 200 226 Q206 222 213 227" fill="none" stroke="${darken(skin, .45)}" stroke-opacity=".5" stroke-width="1.1"/>
    <path d="M194 233 Q200 236 206 233" fill="none" stroke="#ffffff" stroke-opacity=".22" stroke-width="1.4"/>

    ${mark}
    ${frontHair}
    ${crownSvg}
    <rect width="400" height="520" fill="url(#${uid}-vig)" pointer-events="none"/>
  </g>
</svg>`;
}

/* ═══════════════════════════════════════════
   GODSPIRE — styles
   ═══════════════════════════════════════════ */
:root {
  --bg: #07060d;
  --bg-2: #0d0b18;
  --panel: rgba(19, 17, 33, 0.72);
  --panel-2: rgba(27, 24, 46, 0.62);
  --panel-solid: #141126;
  --line: rgba(232, 201, 135, 0.16);
  --line-strong: rgba(232, 201, 135, 0.34);
  --gold: #e8c987;
  --gold-hi: #f8e7b7;
  --gold-dim: #a9854c;
  --text: #eee9f6;
  --muted: #a49db9;
  --muted-2: #7d7793;
  --accent: #7fb8ff;
  --accent-soft: rgba(127, 184, 255, 0.14);
  --danger: #ff8f7a;
  --serif: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, 'Times New Roman', serif;
  --sans: 'Avenir Next', 'Segoe UI', system-ui, -apple-system, 'Helvetica Neue', Arial, sans-serif;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
  --radius: 18px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  overflow: hidden;
}
button { font-family: inherit; color: inherit; cursor: pointer; }
input { font-family: inherit; }
h1, h2, h3, p { margin: 0; }
ol, ul { margin: 0; padding: 0; list-style: none; }
svg { display: block; }
::selection { background: rgba(232, 201, 135, 0.25); color: #fff; }

#starfield {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}
.body-glow {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(900px 700px at 78% -10%, rgba(96, 78, 168, 0.22), transparent 62%),
    radial-gradient(800px 600px at 4% 108%, rgba(60, 130, 138, 0.12), transparent 60%),
    radial-gradient(1000px 800px at 50% 50%, rgba(20, 16, 38, 0.4), transparent 70%);
}
#app { position: relative; z-index: 1; height: 100vh; }
.screen { display: none; height: 100%; flex-direction: column; }
.screen.active { display: flex; animation: screenIn 0.5s ease both; }
@keyframes screenIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ─────────── shared ─────────── */
.panel {
  position: relative;
  background:
    linear-gradient(158deg, rgba(35, 31, 58, 0.66), rgba(12, 11, 22, 0.9) 62%),
    var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}
.panel.ornate {
  background-image:
    linear-gradient(var(--gold-dim), var(--gold-dim)), linear-gradient(var(--gold-dim), var(--gold-dim)),
    linear-gradient(var(--gold-dim), var(--gold-dim)), linear-gradient(var(--gold-dim), var(--gold-dim)),
    linear-gradient(var(--gold-dim), var(--gold-dim)), linear-gradient(var(--gold-dim), var(--gold-dim)),
    linear-gradient(var(--gold-dim), var(--gold-dim)), linear-gradient(var(--gold-dim), var(--gold-dim)),
    linear-gradient(158deg, rgba(35, 31, 58, 0.66), rgba(12, 11, 22, 0.9) 62%);
  background-repeat: no-repeat;
  background-size: 12px 1px, 1px 12px, 12px 1px, 1px 12px, 12px 1px, 1px 12px, 12px 1px, 1px 12px, 100% 100%;
  background-position:
    left 9px top 9px, left 9px top 9px, right 9px top 9px, right 9px top 9px,
    left 9px bottom 9px, left 9px bottom 9px, right 9px bottom 9px, right 9px bottom 9px, 0 0;
  background-color: rgba(12, 11, 22, 0.55);
  opacity: 1;
}
.kicker { font-size: 10px; letter-spacing: 0.26em; text-transform: uppercase; color: var(--gold); opacity: 0.85; }
.label { font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted-2); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 12px 22px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  transition: transform 0.18s ease, box-shadow 0.25s ease, background 0.25s ease, border-color 0.25s ease, opacity 0.2s;
  white-space: nowrap;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0) scale(0.99); }
.btn.primary {
  background: linear-gradient(180deg, #f6e3b4, #d3ab68 55%, #b98f4c);
  color: #1b1524;
  border-color: rgba(255, 241, 200, 0.7);
  box-shadow: 0 10px 30px rgba(190, 146, 71, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.55);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.25);
}
.btn.primary:hover { box-shadow: 0 14px 38px rgba(214, 172, 99, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.6); }
.btn.ghost {
  background: rgba(255, 255, 255, 0.025);
  border-color: var(--line-strong);
  color: var(--text);
}
.btn.ghost:hover { border-color: var(--gold); background: rgba(232, 201, 135, 0.08); }
.btn.small { padding: 9px 15px; font-size: 10.5px; letter-spacing: 0.1em; }
.btn.xl { padding: 15px 30px; font-size: 12.5px; }
.btn:disabled { opacity: 0.4; pointer-events: none; }
.btn-arrow { font-size: 16px; line-height: 1; transition: transform 0.2s; }
.btn:hover .btn-arrow { transform: translateX(4px); }
.icon { width: 18px; height: 18px; flex: none; }
.icon-btn {
  width: 38px; height: 38px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--line);
  color: var(--muted);
  transition: all 0.2s;
}
.icon-btn:hover { color: var(--gold); border-color: var(--line-strong); background: rgba(232, 201, 135, 0.06); }
.icon-btn .icon { width: 17px; height: 17px; }

/* ─────────── title screen ─────────── */
#screen-title { justify-content: space-between; padding: clamp(24px, 4vw, 54px) clamp(24px, 5vw, 76px) 22px; }
.title-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(420px, 1.08fr) minmax(340px, 0.92fr);
  gap: 4vw;
  align-items: center;
  max-width: 1560px;
  width: 100%;
  margin: 0 auto;
}
.title-copy { max-width: 720px; padding-top: 2vh; }
.eyebrow {
  display: flex; align-items: center; gap: 14px;
  font-size: 10.5px; letter-spacing: 0.34em; text-transform: uppercase;
  color: var(--gold); opacity: 0.85; margin-bottom: 22px;
}
.eyebrow .rule { display: block; width: clamp(20px, 4vw, 58px); height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.eyebrow .rule:last-child { transform: scaleX(-1); }
.logo { position: relative; display: flex; flex-direction: column; gap: 0; line-height: 0.9; }
.logo-mark {
  position: absolute; top: -26px; left: 2px;
  font-size: 26px; color: var(--gold); opacity: 0.7;
  animation: floaty 5s ease-in-out infinite;
}
.logo-text {
  font-family: var(--serif);
  font-size: clamp(62px, 9vw, 128px);
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 0.92;
  background: linear-gradient(180deg, #fff6dc 0%, #f0d59b 38%, #c9a260 72%, #967443 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 10px 34px rgba(197, 155, 86, 0.18));
  white-space: nowrap;
}
.tagline {
  margin-top: 30px;
  font-family: var(--serif);
  font-size: clamp(16px, 1.45vw, 21px);
  line-height: 1.7;
  color: #c8c1d8;
  font-weight: 400;
}
.tagline em { color: var(--gold); font-style: italic; }
.title-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 38px; }
.title-meta {
  display: flex; align-items: center; flex-wrap: wrap; gap: 14px;
  margin-top: 46px;
  font-size: 9.5px; letter-spacing: 0.22em; text-transform: uppercase; color: var(--muted-2);
}
.title-meta strong { color: var(--gold); font-weight: 600; }
.title-meta i { width: 3px; height: 3px; background: var(--gold-dim); border-radius: 50%; opacity: 0.7; }
.title-footer {
  display: flex; justify-content: center; gap: 18px; align-items: center;
  font-family: var(--serif); font-size: 12px; color: var(--muted-2); letter-spacing: 0.04em;
  padding-top: 18px;
}
.title-footer .sep { color: var(--gold-dim); font-size: 10px; }

.title-hero {
  position: relative;
  justify-self: center;
  width: min(100%, 500px);
  aspect-ratio: 0.82;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.hero-frame {
  position: relative;
  width: 100%; height: 100%;
  border-radius: 46% 46% 12px 12px / 40% 40% 12px 12px;
  overflow: hidden;
  border: 1px solid rgba(232, 201, 135, 0.22);
  background: radial-gradient(ellipse at 50% 35%, rgba(74, 98, 148, 0.2), rgba(1, 1, 4, 0.1) 62%), linear-gradient(180deg, #0b0914, #050409);
  box-shadow: var(--shadow), inset 0 0 80px rgba(0, 0, 0, 0.5);
  -webkit-mask-image: radial-gradient(ellipse 100% 100% at 50% 55%, #000 62%, transparent 100%);
  mask-image: radial-gradient(ellipse 100% 100% at 50% 55%, #000 62%, transparent 100%);
}
.hero-frame .portrait-svg { width: 100%; height: 100%; }
.orbit {
  position: absolute; border-radius: 50%; pointer-events: none;
  border: 1px solid rgba(232, 201, 135, 0.15);
}
.orbit-a { inset: -4% -7% 4% -7%; border-style: dashed; border-color: rgba(232, 201, 135, 0.16); animation: spin 80s linear infinite; }
.orbit-b { inset: 4% 0 10% 0; border-color: rgba(127, 184, 255, 0.1); animation: spin 120s linear infinite reverse; }
.orbit::before {
  content: ''; position: absolute; top: -3px; left: 50%;
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--gold); box-shadow: 0 0 12px var(--gold);
}
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes floaty { 0%, 100% { transform: translateY(0); opacity: 0.7; } 50% { transform: translateY(-7px); opacity: 1; } }
.hero-plaque {
  position: absolute; bottom: 7%; left: 50%; transform: translateX(-50%);
  text-align: center; pointer-events: none; white-space: nowrap;
}
.hero-plaque span { display: block; font-size: 9px; letter-spacing: 0.36em; text-transform: uppercase; color: var(--gold); margin-bottom: 6px; }
.hero-plaque strong { font-family: var(--serif); font-weight: 500; font-size: 25px; letter-spacing: 0.18em; color: #f4edd9; text-transform: uppercase; }
.portrait-mote { animation: mote 4.5s ease-in-out infinite; }
@keyframes mote { 0%, 100% { opacity: 0.15; transform: translateY(0); } 50% { opacity: 0.85; transform: translateY(-6px); } }
.portrait-orbit { animation: spin 110s linear infinite; }

/* ─────────── topbar / creator ─────────── */
.topbar {
  height: 64px; flex: none;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 clamp(18px, 3vw, 34px);
  border-bottom: 1px solid rgba(232, 201, 135, 0.08);
  background: linear-gradient(180deg, rgba(10, 9, 18, 0.5), transparent);
}
.back-link { background: none; border: 0; color: var(--muted); font-size: 11px; letter-spacing: 0.14em; text-transform: uppercase; padding: 8px 0; transition: color 0.2s; }
.back-link:hover { color: var(--gold); }
.brand-small { font-family: var(--serif); font-size: 15px; letter-spacing: 0.32em; color: var(--gold); }
.brand-small span { margin-right: 8px; opacity: 0.8; }
.step-label { font-size: 9.5px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--muted-2); }

.creator-grid {
  flex: 1; min-height: 0;
  display: grid;
  grid-template-columns: minmax(320px, 390px) minmax(0, 1fr);
  gap: 20px;
  padding: 20px clamp(18px, 3vw, 34px) 24px;
  max-width: 1600px; width: 100%; margin: 0 auto;
}
.preview-card {
  display: flex; flex-direction: column;
  padding: 18px 18px 16px;
  min-height: 0;
  overflow: hidden;
}
.preview-glow {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 70% 45% at 50% 38%, var(--accent-soft), transparent 70%);
  transition: background 0.5s;
}
.preview-frame {
  position: relative; flex: 1; min-height: 0;
  border-radius: 14px;
  background: radial-gradient(ellipse at 50% 42%, rgba(255, 255, 255, 0.03), transparent 60%), rgba(5, 4, 10, 0.4);
  border: 1px solid rgba(232, 201, 135, 0.1);
  overflow: hidden;
  margin-bottom: 14px;
}
.portrait-shell { width: 100%; height: 100%; display: flex; align-items: flex-end; justify-content: center; }
.portrait-shell .portrait-svg { width: 100%; height: 100%; object-fit: contain; }
.creator-portrait { min-height: 0; }
.creator-portrait .portrait-svg { max-height: 100%; }
.frame-corner { position: absolute; width: 24px; height: 24px; border: 1px solid var(--gold); opacity: 0.5; pointer-events: none; }
.frame-corner.tl { top: 9px; left: 9px; border-right: 0; border-bottom: 0; }
.frame-corner.tr { top: 9px; right: 9px; border-left: 0; border-bottom: 0; }
.frame-corner.bl { bottom: 9px; left: 9px; border-right: 0; border-top: 0; }
.frame-corner.br { bottom: 9px; right: 9px; border-left: 0; border-top: 0; }
.preview-info { text-align: center; flex: none; padding: 2px 0 12px; }
.preview-epithet { font-size: 9px; letter-spacing: 0.3em; text-transform: uppercase; color: var(--gold); opacity: 0.85; }
.preview-name { font-family: var(--serif); font-size: 34px; font-weight: 500; letter-spacing: 0.06em; margin-top: 2px; line-height: 1.15; }
.preview-chips { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; margin-top: 12px; }
.preview-chips span {
  font-size: 9px; letter-spacing: 0.13em; text-transform: uppercase;
  border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; color: var(--muted);
  background: rgba(255, 255, 255, 0.02);
}
.preview-chips span:first-child { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 40%, transparent); }
.preview-actions { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex: none; border-top: 1px solid rgba(232, 201, 135, 0.09); padding-top: 14px; }
.preview-hint { font-family: var(--serif); font-style: italic; font-size: 10.5px; color: var(--muted-2); text-align: right; }

.editor-card { display: flex; flex-direction: column; min-height: 0; padding: 26px 28px 20px; }
.editor-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; flex: none; padding-bottom: 18px; border-bottom: 1px solid rgba(232, 201, 135, 0.1); }
.editor-head h1 { font-family: var(--serif); font-weight: 500; font-size: 30px; letter-spacing: 0.02em; line-height: 1.1; margin-top: 4px; }
.editor-head p { max-width: 300px; font-size: 11.5px; color: var(--muted-2); line-height: 1.6; text-align: right; }
.identity-row { display: grid; grid-template-columns: 1fr 1.2fr 1fr; gap: 12px; padding: 16px 0 4px; flex: none; }
.field span { display: block; font-size: 9px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted-2); margin-bottom: 6px; }
.field input {
  width: 100%; height: 40px; padding: 0 12px;
  background: rgba(5, 4, 10, 0.45);
  border: 1px solid var(--line); border-radius: 9px;
  color: var(--text); font-size: 14px; font-family: var(--serif); letter-spacing: 0.02em;
  outline: none; transition: border-color 0.2s, box-shadow 0.2s;
}
.field input:focus { border-color: rgba(232, 201, 135, 0.5); box-shadow: 0 0 0 3px rgba(232, 201, 135, 0.07); }
.tabs { display: flex; gap: 4px; flex: none; border-bottom: 1px solid rgba(232, 201, 135, 0.12); margin-top: 14px; }
.tab {
  position: relative; background: none; border: 0;
  padding: 11px 18px; font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--muted-2); transition: color 0.2s;
}
.tab:hover { color: var(--text); }
.tab.active { color: var(--gold); }
.tab.active::after { content: ''; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 2px; background: linear-gradient(90deg, transparent, var(--gold), transparent); }
.tab-panels { flex: 1; min-height: 0; overflow-y: auto; padding: 18px 4px 8px 0; scrollbar-width: thin; scrollbar-color: rgba(232, 201, 135, 0.25) transparent; }
.tab-panels::-webkit-scrollbar { width: 6px; }
.tab-panels::-webkit-scrollbar-thumb { background: rgba(232, 201, 135, 0.2); border-radius: 3px; }
.field-group { margin-bottom: 22px; }
.field-group:last-child { margin-bottom: 8px; }
.group-label { display: flex; align-items: baseline; gap: 10px; margin-bottom: 10px; }
.group-label strong { font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase; color: #cfc6a6; font-weight: 600; }
.group-label em { font-family: var(--serif); font-style: italic; font-size: 11.5px; color: var(--muted-2); }
.swatches { display: flex; flex-wrap: wrap; gap: 10px; }
.swatch {
  position: relative; width: 34px; height: 34px; border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.3);
  transition: transform 0.15s, box-shadow 0.2s;
}
.swatch:hover { transform: scale(1.1); }
.swatch.selected { box-shadow: 0 0 0 2px var(--bg), 0 0 0 3.5px var(--gold), 0 0 16px rgba(232, 201, 135, 0.35); }
.swatch.selected::after {
  content: '✓'; position: absolute; inset: 0; display: grid; place-items: center;
  font-size: 12px; color: #1a1420; text-shadow: 0 1px 2px rgba(255, 255, 255, 0.5);
}
.options { display: flex; flex-wrap: wrap; gap: 8px; }
.option {
  height: 36px; padding: 0 15px;
  border: 1px solid var(--line); border-radius: 9px;
  background: rgba(255, 255, 255, 0.02);
  font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted);
  transition: all 0.18s;
}
.option:hover { border-color: var(--line-strong); color: var(--text); background: rgba(255, 255, 255, 0.04); }
.option.selected { border-color: var(--gold); color: var(--gold-hi); background: rgba(232, 201, 135, 0.09); box-shadow: inset 0 0 20px rgba(232, 201, 135, 0.05); }
.option-card-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.option-card {
  text-align: left; padding: 13px 14px;
  border: 1px solid var(--line); border-radius: 11px;
  background: rgba(255, 255, 255, 0.02);
  transition: all 0.18s;
}
.option-card:hover { border-color: var(--line-strong); background: rgba(255, 255, 255, 0.04); }
.option-card.selected { border-color: rgba(232, 201, 135, 0.6); background: rgba(232, 201, 135, 0.07); }
.option-card .oc-top { display: flex; align-items: center; gap: 8px; }
.oc-top .icon { width: 15px; height: 15px; color: var(--gold); opacity: 0.8; }
.oc-name { font-size: 12px; font-weight: 600; letter-spacing: 0.04em; color: var(--text); }
.option-card p { margin-top: 5px; font-size: 10.5px; line-height: 1.45; color: var(--muted-2); }
.option-card .oc-mods { margin-top: 7px; font-size: 9px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent); }
.domain-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.domain {
  position: relative; text-align: left; padding: 11px 12px;
  border: 1px solid var(--line); border-radius: 10px;
  background: rgba(255, 255, 255, 0.02); transition: all 0.18s;
}
.domain:hover { border-color: var(--line-strong); background: rgba(255, 255, 255, 0.04); }
.domain .icon { width: 16px; height: 16px; color: var(--dc, var(--gold)); margin-bottom: 6px; opacity: 0.9; }
.domain span { display: block; font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.domain.selected { border-color: var(--dc, var(--gold)); background: color-mix(in srgb, var(--dc, var(--gold)) 12%, transparent); box-shadow: 0 0 20px color-mix(in srgb, var(--dc, var(--gold)) 10%, transparent); }
.domain.selected span { color: var(--text); }
.domain.selected .icon { filter: drop-shadow(0 0 6px var(--dc)); }
.lineage-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
.race-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
.toggle-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 11px; background: rgba(255, 255, 255, 0.02); }
.toggle-row p { font-size: 11px; color: var(--muted-2); }
.toggle-row strong { display: block; font-size: 11.5px; color: var(--text); font-weight: 600; margin-bottom: 2px; }
.switch { position: relative; width: 44px; height: 24px; border-radius: 999px; border: 1px solid var(--line-strong); background: rgba(0, 0, 0, 0.3); transition: background 0.2s; flex: none; }
.switch::after { content: ''; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: var(--muted-2); transition: all 0.2s; }
.switch.on { background: rgba(232, 201, 135, 0.2); border-color: var(--gold); }
.switch.on::after { left: 23px; background: var(--gold-hi); box-shadow: 0 0 10px rgba(232, 201, 135, 0.5); }
.creator-footer { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 20px; border-top: 1px solid rgba(232, 201, 135, 0.1); padding-top: 16px; }
.build-summary { font-size: 10.5px; line-height: 1.6; color: var(--muted-2); max-width: 60%; }
.build-summary b { color: var(--gold); font-weight: 500; }

/* ─────────── game hud ─────────── */
#screen-game { height: 100vh; overflow: hidden; }
.hud {
  flex: none; height: 74px;
  display: flex; align-items: center; gap: 24px;
  padding: 0 clamp(16px, 2.2vw, 30px);
  border-bottom: 1px solid rgba(232, 201, 135, 0.1);
  background: linear-gradient(180deg, rgba(12, 10, 22, 0.72), rgba(8, 7, 14, 0.3));
  backdrop-filter: blur(12px);
}
.hud-id { display: flex; align-items: center; gap: 13px; min-width: 0; }
.rank-crest {
  width: 42px; height: 42px; flex: none;
  display: grid; place-items: center;
  border: 1px solid var(--line-strong);
  transform: rotate(45deg); border-radius: 9px;
  background: radial-gradient(circle, var(--accent-soft), transparent 70%);
  color: var(--accent);
}
.rank-crest svg { transform: rotate(-45deg); width: 20px; height: 20px; }
.hud-name { display: flex; align-items: baseline; gap: 10px; }
.hud-name > span:first-child { font-family: var(--serif); font-size: 20px; letter-spacing: 0.05em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-rank { font-size: 8.5px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--gold); border: 1px solid var(--line); padding: 2px 7px; border-radius: 999px; white-space: nowrap; }
.hud-epithet { font-size: 9.5px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted-2); margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-might { margin-left: auto; display: flex; align-items: baseline; gap: 8px; white-space: nowrap; }
.hud-might .label { font-size: 8.5px; letter-spacing: 0.18em; }
.hud-might strong { font-family: var(--serif); font-size: 25px; font-weight: 500; color: var(--gold-hi); letter-spacing: 0.03em; }
.hud-standing { font-size: 10px; color: var(--gold); border: 1px solid var(--line); border-radius: 999px; padding: 2px 8px; }
.hud-right { display: flex; align-items: center; gap: 9px; }
.hud-aeon { text-align: right; margin-right: 6px; }
.hud-aeon span { display: block; font-family: var(--serif); font-size: 15px; letter-spacing: 0.08em; color: #ded5ec; line-height: 1.2; }
.hud-aeon small { display: block; font-size: 8.5px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted-2); }

.game-main {
  flex: 1; min-height: 0;
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr) 320px;
  gap: 15px;
  padding: 15px clamp(14px, 2vw, 26px) 18px;
  max-width: 1600px; width: 100%; margin: 0 auto;
}
.col { min-height: 0; }
.col-god { display: flex; flex-direction: column; padding: 14px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(232, 201, 135, 0.2) transparent; }
.col-god::-webkit-scrollbar { width: 5px; }
.col-god::-webkit-scrollbar-thumb { background: rgba(232, 201, 135, 0.18); border-radius: 3px; }
.mini-portrait {
  position: relative; height: 188px; flex: none; border-radius: 12px; overflow: hidden;
  background: radial-gradient(ellipse at 50% 42%, var(--accent-soft), transparent 68%), rgba(4, 3, 9, 0.35);
  border: 1px solid rgba(232, 201, 135, 0.09);
  margin-bottom: 10px;
}
.mini-portrait .portrait-svg { width: 100%; height: 135%; margin-top: -4%; }
.god-title { text-align: center; flex: none; }
.god-name { font-family: var(--serif); font-size: 23px; letter-spacing: 0.04em; line-height: 1.15; }
.god-sub { font-size: 8.5px; letter-spacing: 0.19em; text-transform: uppercase; color: var(--gold); margin-top: 4px; }
.might-block { margin-top: 13px; flex: none; }
.might-line { display: flex; justify-content: space-between; align-items: baseline; }
.might-line span { font-size: 8.5px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted-2); }
.might-line strong { font-family: var(--serif); font-size: 18px; font-weight: 500; color: var(--gold-hi); }
.might-bar { position: relative; height: 5px; background: rgba(255, 255, 255, 0.06); border-radius: 99px; margin-top: 6px; overflow: hidden; }
.might-bar i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 99px; background: linear-gradient(90deg, #9c7434, var(--gold), #fff0c2); box-shadow: 0 0 10px rgba(232, 201, 135, 0.5); transition: width 0.6s cubic-bezier(.2,.7,.2,1); }
.might-next { font-size: 9px; color: var(--muted-2); margin-top: 5px; font-family: var(--serif); font-style: italic; }
.followers-block { margin-top: 12px; padding: 10px 12px; border-radius: 10px; background: rgba(255, 255, 255, 0.025); border: 1px solid rgba(232, 201, 135, 0.08); flex: none; }
.followers-block > div { display: flex; align-items: baseline; gap: 8px; margin-top: 2px; }
.followers-block strong { font-family: var(--serif); font-size: 26px; font-weight: 500; color: #f4e9cf; line-height: 1; }
.trend { font-size: 9px; letter-spacing: 0.04em; color: #8fd8a8; }
.trend.down { color: var(--danger); }
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 9px; flex: none; }
.stat-cell { display: flex; align-items: center; gap: 8px; padding: 8px 9px; border-radius: 9px; background: rgba(255, 255, 255, 0.025); border: 1px solid rgba(255, 255, 255, 0.035); }
.stat-cell .icon { width: 15px; height: 15px; color: var(--gold); opacity: 0.75; }
.stat-cell .sv { font-family: var(--serif); font-size: 15px; line-height: 1; }
.stat-cell .sl { display: block; font-size: 7.5px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted-2); margin-top: 2px; }
.btn.ascend {
  margin-top: 11px; flex: none; width: 100%;
  flex-direction: column; gap: 1px; border-radius: 10px; padding: 10px 12px;
  background: rgba(232, 201, 135, 0.06); border: 1px solid var(--line);
  color: var(--muted); font-size: 10px; letter-spacing: 0.16em;
}
.btn.ascend .asc-main { font-size: 10.5px; letter-spacing: 0.14em; color: var(--gold); display: flex; align-items: center; gap: 7px; }
.btn.ascend .asc-main .icon { width: 13px; height: 13px; }
.btn.ascend .asc-sub { font-size: 8px; letter-spacing: 0.1em; text-transform: none; color: var(--muted-2); }
.btn.ascend.ready {
  background: linear-gradient(180deg, rgba(246, 227, 180, 0.96), rgba(197, 153, 84, 0.96));
  border-color: #ffefc2; color: #211929;
  box-shadow: 0 8px 26px rgba(214, 172, 99, 0.3);
  animation: ascendPulse 2.6s ease-in-out infinite;
}
.btn.ascend.ready .asc-main { color: #241b2b; }
.btn.ascend.ready .asc-sub { color: rgba(36, 27, 43, 0.7); }
@keyframes ascendPulse { 0%, 100% { box-shadow: 0 8px 26px rgba(214, 172, 99, 0.22); } 50% { box-shadow: 0 8px 36px rgba(232, 201, 135, 0.5); } }
.btn.ascend:disabled { opacity: 0.6; }
.card-section { margin-top: 13px; flex: none; }
.section-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 7px; font-size: 8px; letter-spacing: 0.17em; text-transform: uppercase; color: var(--muted-2); }
.mini-link { background: none; border: 0; padding: 0; font-size: 8px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--gold-dim); border-bottom: 1px solid rgba(232, 201, 135, 0.25); }
.mini-link:hover { color: var(--gold); }
.section-count { color: var(--muted-2); }
.race-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.race-chip { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.06); background: rgba(255, 255, 255, 0.03); font-size: 9px; color: var(--muted); cursor: pointer; transition: all 0.2s; }
.race-chip:hover { border-color: var(--line-strong); color: var(--text); }
.race-chip .dot { width: 6px; height: 6px; border-radius: 50%; flex: none; box-shadow: 0 0 6px currentColor; }
.relic-list { display: flex; flex-direction: column; gap: 3px; }
.relic-row { display: flex; align-items: center; gap: 7px; padding: 4px 2px; font-size: 10px; color: var(--muted); cursor: pointer; border-bottom: 1px dashed rgba(255, 255, 255, 0.05); }
.relic-row:hover { color: var(--text); }
.relic-row .icon { width: 12px; height: 12px; color: var(--gold); opacity: 0.7; }
.relic-row span { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.relic-row b { font-weight: 500; font-size: 9px; color: var(--gold-dim); }
.relic-empty { font-family: var(--serif); font-style: italic; font-size: 10.5px; color: var(--muted-2); }

.col-realm { display: flex; flex-direction: column; gap: 12px; min-height: 0; }
.aeon-bar { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 11px 16px; }
.aeon-title { display: flex; align-items: baseline; gap: 12px; }
.aeon-num { font-family: var(--serif); font-size: 19px; letter-spacing: 0.1em; color: #efe6d2; }
.aeon-sub { font-size: 8.5px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--muted-2); }
.ap-wrap { display: flex; align-items: center; gap: 10px; }
.ap-wrap > span { font-size: 8px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted-2); }
.ap-pips { display: flex; gap: 6px; }
.ap-pip { width: 15px; height: 15px; transform: rotate(45deg); border: 1px solid var(--line-strong); border-radius: 3px; background: rgba(255, 255, 255, 0.02); transition: all 0.3s; }
.ap-pip.full { background: linear-gradient(135deg, #f7e3b0, #cda25f); border-color: #fff0c2; box-shadow: 0 0 12px rgba(232, 201, 135, 0.45); }
.actions-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; flex: none; }
.action {
  position: relative; display: flex; align-items: center; gap: 11px;
  padding: 10px 12px; min-height: 69px;
  text-align: left; border: 1px solid var(--line); border-radius: 12px;
  background: linear-gradient(140deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012));
  transition: transform 0.16s, border-color 0.2s, background 0.2s, box-shadow 0.2s;
  overflow: hidden;
}
.action:hover:not(.disabled) { transform: translateY(-2px); border-color: rgba(232, 201, 135, 0.4); background: linear-gradient(140deg, rgba(232, 201, 135, 0.07), rgba(255, 255, 255, 0.02)); box-shadow: 0 8px 22px rgba(0, 0, 0, 0.25); }
.action:active:not(.disabled) { transform: translateY(0); }
.action .a-icon { width: 34px; height: 34px; flex: none; border-radius: 9px; display: grid; place-items: center; border: 1px solid rgba(232, 201, 135, 0.14); background: rgba(5, 4, 10, 0.35); color: var(--gold); }
.action .a-icon .icon { width: 17px; height: 17px; }
.action .a-body { min-width: 0; flex: 1; }
.action .a-name { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }
.action .a-name strong { font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; color: #ebe2f5; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.action .a-cost { font-size: 8px; letter-spacing: 0.08em; color: var(--gold-dim); white-space: nowrap; text-transform: uppercase; }
.action .a-desc { font-size: 9.5px; color: var(--muted-2); line-height: 1.35; margin-top: 3px; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.action.disabled { opacity: 0.42; cursor: not-allowed; }
.action.disabled .a-cost { color: var(--danger); }
.action.flash { animation: actionFlash 0.5s ease; }
@keyframes actionFlash { 0% { background: rgba(232, 201, 135, 0.22); border-color: var(--gold); } 100% { background: linear-gradient(140deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012)); } }
.chronicle { flex: 1; min-height: 96px; display: flex; flex-direction: column; overflow: hidden; padding: 12px 14px 6px; }
.chronicle header { flex: none; display: flex; align-items: baseline; justify-content: space-between; padding-bottom: 8px; border-bottom: 1px solid rgba(232, 201, 135, 0.08); }
.chronicle header span { font-size: 9px; letter-spacing: 0.22em; text-transform: uppercase; color: var(--gold); }
.chronicle header small { font-family: var(--serif); font-style: italic; font-size: 9.5px; color: var(--muted-2); }
.log { flex: 1; overflow-y: auto; padding: 6px 2px 6px 0; scrollbar-width: thin; scrollbar-color: rgba(232, 201, 135, 0.18) transparent; }
.log::-webkit-scrollbar { width: 5px; }
.log::-webkit-scrollbar-thumb { background: rgba(232, 201, 135, 0.16); border-radius: 3px; }
.log-entry { display: flex; gap: 9px; padding: 6px 2px; border-bottom: 1px solid rgba(255, 255, 255, 0.035); animation: logIn 0.4s ease both; }
@keyframes logIn { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: none; } }
.log-entry .le-icon { width: 22px; height: 22px; flex: none; display: grid; place-items: center; border-radius: 6px; background: rgba(255, 255, 255, 0.03); color: var(--gold); }
.log-entry .le-icon .icon { width: 12px; height: 12px; }
.log-entry .le-text { flex: 1; font-size: 10.5px; line-height: 1.5; color: #bab2cc; }
.log-entry .le-aeon { flex: none; font-size: 8px; letter-spacing: 0.1em; color: var(--muted-2); padding-top: 2px; text-transform: uppercase; }
.log-entry.tone-faith .le-icon { color: #ffd77a; }
.log-entry.tone-power .le-icon, .log-entry.tone-rival .le-icon { color: #ff9d7a; }
.log-entry.tone-wisdom .le-icon { color: #a9d8ff; }
.log-entry.tone-influence .le-icon { color: #d0b3ff; }
.log-entry.tone-rank .le-icon { color: var(--gold-hi); background: rgba(232, 201, 135, 0.1); }
.log-entry.tone-divine .le-text { color: #e3d9c0; font-family: var(--serif); font-size: 11.5px; }
.end-turn {
  flex: none; height: 52px; border: 1px solid rgba(255, 241, 200, 0.55);
  border-radius: 12px; display: flex; align-items: center; justify-content: center; gap: 10px;
  background: linear-gradient(100deg, #efd9a5, #d6ad6b 52%, #c19754);
  color: #1e1728; box-shadow: 0 10px 26px rgba(186, 143, 68, 0.22), inset 0 1px 0 rgba(255,255,255,.5);
  transition: transform 0.18s, box-shadow 0.2s;
}
.end-turn:hover { transform: translateY(-1px); box-shadow: 0 14px 34px rgba(205, 163, 88, 0.34); }
.end-turn > span:first-child { font-size: 12px; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase; }
.end-turn small { font-family: var(--serif); font-style: italic; font-size: 10.5px; opacity: 0.65; }
.end-arrow { font-size: 18px; margin-left: 4px; transition: transform 0.2s; }
.end-turn:hover .end-arrow { transform: translateX(4px); }

.col-board { display: flex; flex-direction: column; padding: 16px 14px 12px; overflow: hidden; }
.board-head { flex: none; display: flex; justify-content: space-between; align-items: flex-start; padding: 0 4px 12px; border-bottom: 1px solid rgba(232, 201, 135, 0.1); }
.board-kicker { font-size: 8px; letter-spacing: 0.26em; text-transform: uppercase; color: var(--gold-dim); margin-bottom: 2px; }
.board-head h2 { font-family: var(--serif); font-weight: 500; font-size: 21px; letter-spacing: 0.03em; line-height: 1.1; }
.board-crown { color: var(--gold); opacity: 0.8; }
.board-crown .icon { width: 20px; height: 20px; }
.leaderboard { flex: 1; overflow-y: auto; padding: 6px 0; scrollbar-width: thin; scrollbar-color: rgba(232, 201, 135, 0.18) transparent; }
.leaderboard::-webkit-scrollbar { width: 5px; }
.leaderboard::-webkit-scrollbar-thumb { background: rgba(232, 201, 135, 0.16); border-radius: 3px; }
.throne {
  display: grid; grid-template-columns: 20px 26px minmax(0, 1fr) auto;
  align-items: center; gap: 7px;
  padding: 5.5px 8px; border-radius: 8px; border: 1px solid transparent;
  cursor: pointer; transition: background 0.18s, border-color 0.18s;
  position: relative;
}
.throne:hover { background: rgba(255, 255, 255, 0.03); }
.throne + .throne { margin-top: 1px; }
.throne .t-rank { font-family: var(--serif); font-size: 11px; color: var(--muted-2); text-align: center; }
.throne .t-sigil { width: 23px; height: 23px; border-radius: 50%; display: grid; place-items: center; border: 1px solid rgba(255, 255, 255, 0.09); background: rgba(255, 255, 255, 0.03); }
.throne .t-sigil .icon { width: 11px; height: 11px; }
.throne .t-info { min-width: 0; }
.throne .t-name { font-family: var(--serif); font-size: 12.5px; color: #d8d0e6; line-height: 1.25; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.throne .t-sub { font-size: 7.5px; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-2); line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.throne .t-might { text-align: right; font-size: 10.5px; color: #bdb3cd; font-variant-numeric: tabular-nums; }
.throne .t-trend { display: block; font-size: 7px; letter-spacing: 0.04em; color: var(--muted-2); }
.throne .t-trend.up { color: #7fc99a; }
.throne .t-trend.down { color: #e08080; }
.throne.you { background: linear-gradient(90deg, rgba(232, 201, 135, 0.14), rgba(232, 201, 135, 0.04)); border-color: rgba(232, 201, 135, 0.38); }
.throne.you .t-name { color: var(--gold-hi); }
.throne.you .t-rank { color: var(--gold); }
.throne.you .t-might { color: var(--gold-hi); }
.throne.top .t-rank { color: var(--gold); }
.throne .you-tag { font-size: 6.5px; letter-spacing: 0.16em; color: var(--gold); border: 1px solid rgba(232, 201, 135, 0.4); border-radius: 3px; padding: 1px 4px; margin-left: 5px; vertical-align: 1px; }
.board-footer { flex: none; border-top: 1px solid rgba(232, 201, 135, 0.1); padding: 10px 4px 0; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.standing-text { font-size: 9px; letter-spacing: 0.06em; color: var(--muted-2); }
