function run(seedDomain='storm', seedLineage='celestial', verbose=false) {
  const draft={name:'Sim',epithet:'x',pantheon:'x',domain:seedDomain,lineage:seedLineage,race:'humans',appearance:{}};
  let s=newGame(draft, Math.random);
  let ascended=[];
  for(let turn=1; turn<=40; turn++){
    // ascend if possible
    while(canAscend(s)){ const info=ascend(s); ascended.push([turn,info.to.name,computeMight(s)]); }
    // forge race at certain turns if affordable
    if([4,9,14].includes(turn) && s.races.length<4 && s.ap>=2 && s.stats.faith>=30 && s.stats.power>=12){
      const traits=['arcane','zealous','feral','tidal'];
      const t=TRAITS[(turn/5|0)%4];
      s.ap-=2;s.stats.faith-=30;s.stats.power-=12;s.followers=Math.round(s.followers*1.18);
      s.races.push({name:'x',mods:{...t.mods}});
    }
    // forge relic when possible every ~3 turns
    if(turn%3===0 && s.ap>=2 && s.stats.faith>=20 && s.stats.power>=8 && s.relics.length<6){
      performAction(s,'relic',Math.random);
    }
    let guard=0;
    while(s.ap>0 && guard++<10){
      let pick;
      if(s.stats.faith>=14 && s.ap>=1 && turn%4===0) pick='miracle';
      else if(s.stats.faith>=14 && s.stats.influence<25) pick='festival';
      else if(s.stats.faith>=10 && s.stats.wisdom<40) pick='prophecy';
      else if(s.ap>=1) pick='prayers';
      const r=performAction(s,pick,Math.random);
      if(!r.ok){ const r2=performAction(s,'meditate',Math.random); if(!r2.ok) break; }
    }
    // spend leftover AP on meditate
    while(s.ap>0){ const r=performAction(s,'meditate',Math.random); if(!r.ok) break; }
    const res=endAeon(s, Math.random);
    if(res.event){ const ch=res.event.choices.find(c=>!(c.effects.faith<0 && s.stats.faith<-c.effects.faith)); if(ch) applyEventChoice(s,ch); }
    if(verbose) console.log(turn, RANKS[s.rank].name, computeMight(s), 'souls', Math.round(s.followers), 'f', Math.round(s.stats.faith), 'rank#', standing(s).rank, 'ap', s.ap);
