  }
  console.log('NO SUPREME after 40 turns', RANKS[s.rank].name, computeMight(s), 'souls', Math.round(s.followers), 'stand', standing(s).rank);
  return {turn:40,might:computeMight(s),stand:standing(s).rank,ascended};
}

