import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const base = 'http://localhost:3002';
const outDir = '/home/runner/work/PlayGround/PlayGround/screenshots';
const errors = [];

const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox','--force-device-scale-factor=1'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push('HTTP ' + r.status() + ' ' + r.url()); });

async function shot(name) {
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${outDir}/${name}.jpg`, type: 'jpeg', quality: 72 });
  console.log('shot', name);
}

await page.goto(base, { waitUntil: 'networkidle' });
await page.waitForTimeout(1000);
await shot('m-title');

await page.click('#beginBtn');
await page.waitForTimeout(700);
await shot('m-creator');

// scroll creator to editor tabs to check mobile stacking
await page.locator('#creatorTabs').scrollIntoViewIfNeeded();
await shot('m-creator-tabs');
await page.click('#beginGameBtn');
await page.waitForTimeout(900);
await shot('m-game-realm');

await page.click('.mobile-tabs [data-mtab="god"]');
await shot('m-game-self');
await page.click('.mobile-tabs [data-mtab="board"]');
await shot('m-game-thrones');
await page.click('.mobile-tabs [data-mtab="realm"]');

// interaction chain: take first available action x2, end aeon
const actionSel = '.action-card:not([disabled])';
const n = await page.locator(actionSel).count();
console.log('available actions', n);
if (n) { await page.locator(actionSel).first().click(); await page.waitForTimeout(500); }
await shot('m-after-action');

// end aeon and handle event if appears
await page.click('#endTurnBtn');
await page.waitForTimeout(900);
const modalVisible = await page.locator('#modalRoot .modal').count();
console.log('modal after end turn', modalVisible);
if (modalVisible) {
  await shot('m-event');
  const choice = page.locator('#modalRoot .choice-btn, #modalRoot .event-choice, #modalRoot button').first();
  const txt = await choice.textContent().catch(()=>null);
  console.log('clicking choice', txt && txt.trim().slice(0,50));
  await choice.click().catch(e=>errors.push('CHOICEFAIL ' + e.message));
  await page.waitForTimeout(800);
  await page.locator('#modalRoot .modal-close, #modalRoot [data-close]').first().click().catch(()=>{});
  await page.waitForTimeout(400);
}
await shot('m-after-turn');

// reload -> continue flow
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(800);
const contVisible = await page.locator('#continueBtn').isVisible();
console.log('continue visible', contVisible);
await shot('m-title-continue');
if (contVisible) {
  await page.click('#continueBtn');
  await page.waitForTimeout(800);
  console.log('after continue screen game', await page.locator('#screen-game.active').count());
  await shot('m-continued');
}

console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

