import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.click('#beginBtn'); await page.waitForTimeout(400);
await page.click('#beginGameBtn'); await page.waitForTimeout(600);
const data = await page.evaluate(() => [...document.querySelectorAll('.action')].map(el => ({
  id: el.dataset.action,
  name: el.querySelector('strong')?.textContent,
  cost: el.querySelector('.a-cost')?.textContent,
  costRect: el.querySelector('.a-cost')?.getBoundingClientRect(),
  rect: el.getBoundingClientRect(),
})));
console.log(JSON.stringify(data.slice(0,4), null, 2));
console.log('debug keys', await page.evaluate(() => Object.keys(window.godspire || {})));
await browser.close();

