async function makePage(mobile = false) {
  const ctx = await browser.newContext({
    viewport: mobile ? { width: 390, height: 844 } : { width: 1440, height: 900 },
    deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile,
  });
  const page = await ctx.newPage();
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  page.on('response', r => { if (r.status() >= 400) errors.push('HTTP ' + r.status() + ' ' + r.url()); });
  await page.goto(base, { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  return page;
}

async function start(page) {
  await page.click('#beginBtn');
  await page.waitForTimeout(400);
  await page.click('#beginGameBtn');
  await page.waitForTimeout(700);
}

// ---------- desktop flow ----------
const page = await makePage(false);
await start(page);

const s0 = await page.evaluate(() => ({ aeon: godspire.state.aeon, ap: godspire.state.ap, followers: godspire.state.followers, rank: godspire.state.rank, log: godspire.state.log.length }));
log('initial', s0);

// action
await page.click('.action[data-action="prayers"]');
await page.waitForTimeout(600);
const s1 = await page.evaluate(() => ({ ap: godspire.state.ap, followers: godspire.state.followers, log: godspire.state.log.length, toast: document.querySelector('#toastRoot')?.innerText?.trim() }));
log('after prayers', s1);

// end aeon
await page.click('#endTurnBtn');
await page.waitForTimeout(900);
// handle event if shown
let modalSeen = false;
for (let i = 0; i < 6; i++) {
  const hasModal = await page.locator('#modalRoot .modal').count();
  if (hasModal) {
    modalSeen = true;
    await page.screenshot({ path: `${out}/flow-event.jpg`, type: 'jpeg', quality: 72 });
    const enabled = page.locator('#modalRoot .choice:not([disabled])').first();
    if (await enabled.count()) {
      await enabled.click();
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${out}/flow-event-result.jpg`, type: 'jpeg', quality: 72 });
      await page.locator('#modalRoot [data-close]').first().click();
      await page.waitForTimeout(300);
    }
  }
  if (!hasModal) break;
}
const s2 = await page.evaluate(() => ({ aeon: godspire.state.aeon, ap: godspire.state.ap, followers: godspire.state.followers, rivals: godspire.state.rivals[0].might, event: godspire.state.pendingEvent || null }));
log('after end aeon', s2, 'modalSeen', modalSeen);

// force an event for deterministic choice test
await page.evaluate(() => godspire.openEvent());
await page.waitForTimeout(400);
const choices = await page.locator('#modalRoot .choice').count();
log('forced event choices', choices);
if (choices) {
  await page.locator('#modalRoot .choice:not([disabled])').first().click();
  await page.waitForTimeout(500);
  const resultText = await page.locator('#modalRoot .modal-text').last().textContent().catch(()=>null);
  log('event result modal', !!resultText, (resultText||'').slice(0,60));
  await page.locator('#modalRoot [data-close]').first().click();
  await page.waitForTimeout(300);
}

// forge race (give resources)
await page.evaluate(() => { Object.assign(godspire.state.stats, { faith: 80, power: 40 }); godspire.state.ap = 3; godspire.render(); });
await page.click('#openRaceBtn');
await page.waitForTimeout(600);
log('forge open', await page.locator('#modalRoot .modal').count(), 'confirm disabled', await page.locator('#forgeConfirm').isDisabled());
await page.fill('#forgeName', 'The Ashen Choir');
await page.locator('#modalRoot [data-trait="fervent"]').click().catch(()=>{});
await page.locator('#modalRoot [data-form="2"]').click().catch(()=>{});
const beforeForge = await page.evaluate(() => ({ races: godspire.state.races.length, followers: godspire.state.followers, ap: godspire.state.ap }));
await page.screenshot({ path: `${out}/flow-forge.jpg`, type: 'jpeg', quality: 72 });
await page.click('#forgeConfirm');
await page.waitForTimeout(700);
const afterForge = await page.evaluate(() => ({ races: godspire.state.races.length, followers: godspire.state.followers, ap: godspire.state.ap, lastRace: godspire.state.races.at(-1)?.name }));
log('forge result', beforeForge, '->', afterForge);

// ascend
await page.evaluate(() => { godspire.state.followers = 300000; godspire.state.stats.faith = 200; godspire.state.stats.power = 120; godspire.render(); });
await page.waitForTimeout(400);
const asc = await page.locator('#ascendBtn').evaluate(el => ({ text: el.textContent.trim(), disabled: el.disabled, cls: el.className })).catch(()=>null);
log('ascend button', asc);
if (asc && !asc.disabled) {
  await page.click('#ascendBtn');
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${out}/flow-ascend.jpg`, type: 'jpeg', quality: 72 });
  log('ascend modal', await page.locator('#modalRoot .modal').count());
  await page.locator('#modalRoot [data-close]').first().click();
  await page.waitForTimeout(400);
  log('rank after', await page.evaluate(() => godspire.state.rank));
}

// save + reload + continue
const beforeReload = await page.evaluate(() => ({ aeon: godspire.state.aeon, followers: godspire.state.followers, rank: godspire.state.rank, races: godspire.state.races.length, log: godspire.state.log.length }));
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(800);
const cont = await page.locator('#continueBtn').isVisible();
await page.click('#continueBtn');
await page.waitForTimeout(800);
const afterReload = await page.evaluate(() => ({ aeon: godspire.state.aeon, followers: godspire.state.followers, rank: godspire.state.rank, races: godspire.state.races.length, log: godspire.state.log.length }));
log('persistence', cont, beforeReload, afterReload);

// guide + menu
await page.click('#menuBtn'); await page.waitForTimeout(500);
log('menu modal', await page.locator('#modalRoot .modal').count());
await page.screenshot({ path: `${out}/flow-menu.jpg`, type: 'jpeg', quality: 72 });
await page.locator('#modalRoot [data-close]').first().click();

log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

