import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const errors = [];
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type()==='error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.click('#beginBtn'); await page.waitForTimeout(300); await page.click('#beginGameBtn'); await page.waitForTimeout(700);

// jump to one ascension from victory
await page.evaluate(() => {
  godspire.state.rank = 7;
  godspire.state.followers = 5000000;
  godspire.state.stats.faith = 3000;
  godspire.state.stats.power = 1000;
  godspire.render();
});
await page.waitForTimeout(300);
console.log('rank/might', await page.evaluate(() => ({ rank: godspire.state.rank, might: godspire.state.might })));
const ready = await page.locator('#ascendBtn').evaluate(el => ({ disabled: el.disabled, text: el.textContent.trim() }));
console.log('ascend', ready);
await page.click('#ascendBtn'); await page.waitForTimeout(600);
console.log('victory modal', await page.locator('#modalRoot .victory').count(), 'buttons', await page.locator('#modalRoot .modal-actions .btn').allTextContents());
await page.screenshot({ path: `${out}/victory.jpg`, type: 'jpeg', quality: 75 });
await page.locator('#modalRoot [data-new]').click(); await page.waitForTimeout(700);
console.log('new flow screen', await page.locator('#screen-create.active').count(), 'modal', await page.locator('#modalRoot .modal').count());
// create and start new god from reset draft
await page.fill('#godName', 'Testara');
await page.click('#beginGameBtn'); await page.waitForTimeout(700);
console.log('new game', await page.evaluate(() => ({ name: godspire.state.god.name, aeon: godspire.state.aeon, rank: godspire.state.rank })));
console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

